/*! Auth-bridge-aware derivative of coi-serviceworker v0.1.7.
 * Guido Zuidhof and contributors, licensed under MIT.
 */
(() => {
  if (typeof window === "undefined") {
    let coepCredentialless = false;

    self.addEventListener("install", () => self.skipWaiting());
    self.addEventListener("activate", (event) => {
      event.waitUntil(self.clients.claim());
    });
    self.addEventListener("message", (event) => {
      if (event.data?.type === "deregister") {
        event.waitUntil(
          self.registration.unregister()
            .then(() => self.clients.matchAll())
            .then((clients) => {
              for (const client of clients) client.navigate(client.url);
            }),
        );
      } else if (event.data?.type === "coepCredentialless") {
        coepCredentialless = event.data.value;
      }
    });
    self.addEventListener("fetch", (event) => {
      const request = event.request;
      if (request.cache === "only-if-cached" && request.mode !== "same-origin") {
        return;
      }
      const fetchRequest = coepCredentialless && request.mode === "no-cors"
        ? new Request(request, { credentials: "omit" })
        : request;
      event.respondWith(fetch(fetchRequest).then((response) => {
        if (response.status === 0) return response;
        const headers = new Headers(response.headers);
        const url = new URL(request.url);
        const authBridgeNavigation = request.mode === "navigate"
          && url.pathname.endsWith("/google-auth.html");

        headers.set("Cross-Origin-Resource-Policy", "cross-origin");
        if (request.mode === "navigate") {
          if (authBridgeNavigation) {
            headers.delete("Cross-Origin-Embedder-Policy");
            headers.set(
              "Cross-Origin-Opener-Policy",
              "same-origin-allow-popups",
            );
          } else {
            headers.set(
              "Cross-Origin-Embedder-Policy",
              coepCredentialless ? "credentialless" : "require-corp",
            );
            headers.set("Cross-Origin-Opener-Policy", "same-origin");
          }
        }
        return new Response(response.body, {
          status: response.status,
          statusText: response.statusText,
          headers,
        });
      }).catch((error) => console.error(error)));
    });
    return;
  }

  const configuration = {
    shouldRegister: () => true,
    shouldDeregister: () => false,
    coepCredentialless: () => !(window.chrome || window.netscape),
    // Most stores do not need shared memory. The viewer performs an explicit
    // controlled navigation when a source declares that it needs isolation.
    doReload: () => {},
    quiet: true,
    ...window.coi,
  };
  const serviceWorker = navigator.serviceWorker;
  if (!serviceWorker) return;

  if (serviceWorker.controller) {
    serviceWorker.controller.postMessage({
      type: "coepCredentialless",
      value: configuration.coepCredentialless(),
    });
    if (configuration.shouldDeregister()) {
      serviceWorker.controller.postMessage({ type: "deregister" });
    }
  }
  if (!configuration.shouldRegister() || !window.isSecureContext) return;

  serviceWorker.register(document.currentScript.src).then((registration) => {
    registration.addEventListener("updatefound", configuration.doReload);
    if (registration.active && !serviceWorker.controller) {
      configuration.doReload();
    }
  }).catch((error) => {
    if (!configuration.quiet) {
      console.error("COOP/COEP service worker registration failed", error);
    }
  });
})();
